// Port of tests/Filee.Engines.Tests/MediaTests.cs (and the FFmpeg parts of PortableEngineTests / OwnCopyTests): routes,
// command-line choices (no FFmpeg needed) and real conversions, which run only when FFmpeg is installed. Inputs are
// generated by FFmpeg itself (test pattern + sine tone) and every output is checked with ffprobe. Targets whose encoder
// the installed FFmpeg lacks (Homebrew's: libvorbis, libtheora, libopencore_amrnb) are skipped and listed.

import Foundation
import XCTest
@testable import FileToXEngineKit

final class MediaTests: XCTestCase {
    private static let tools = FfmpegConverter.locate()
    private static let hd = VideoStreamInfo(1920, 1080, 1, 0, 29.97)
    private let converter = FfmpegConverter()
    private var root = ""

    override func setUpWithError() throws {
        root = FilePath.combine(NSTemporaryDirectory(), "filetox-media-tests", String(ArchiveFiles.guid().prefix(8)))
        try FileManager.default.createDirectoryIfNeeded(root)
    }

    override func tearDownWithError() throws {
        FileManager.default.removeIfPresent(root)
    }

    private func newFolder() throws -> String {
        let dir = FilePath.combine(root, String(ArchiveFiles.guid().prefix(6)))
        try FileManager.default.createDirectoryIfNeeded(dir)
        return dir
    }

    private func skipUnlessInstalled() throws {
        try XCTSkipUnless(Self.tools != nil, "FFmpeg is not installed (select a full FFmpeg build in the engine settings)")
    }

    // ───────────────────────── Routes (no FFmpeg needed) ─────────────────────────

    func testMediaConversionsTakeOneFfmpegStep() {
        let pairs = [("mp4", "webm"), ("mov", "mp4"), ("mkv", "mp4"), ("avi", "mp4"), ("mp4", "mp4"), ("mp4", "gif"), ("mp4", "mp3"),
                     ("webm", "m4a"), ("wav", "mp3"), ("flac", "mp3"), ("mp3", "mp3"), ("m4a", "wav"), ("amr", "mp3"), ("gif", "mp4"),
                     ("gif", "webm"), ("rm", "mp4"), ("dss", "mp3")]
        for (from, to) in pairs { XCTAssertEqual(ArchiveBuilders.route(from, to, converter.edges)?.count, 1, "\(from) → \(to)") }
    }

    /// Filee checks the whole route (ffmpeg → png → image engine); here the edge costs that make the planner choose it.
    func testVideoToImagesGoesThroughOneStillFrameNotAnAnimatedGif() {
        for (from, to) in [("mp4", "jpg"), ("mkv", "webp"), ("mov", "pdf")] {
            XCTAssertFalse(converter.edges.contains { $0.from == from && $0.to == to }, "\(from) → \(to)")
            XCTAssertEqual(converter.edges.first { $0.from == from && $0.to == "png" }?.cost, 10)
            XCTAssertEqual(converter.edges.first { $0.from == from && $0.to == "gif" }?.cost, 15)
        }
    }

    func testEveryWritableVideoAndAudioFormatIsATarget() {
        // A new format in the catalog must get an encoding (or a documented reason why not) in MediaEncoding.
        XCTAssertEqual(FormatRegistry.known.filter { $0.category == .video && $0.writable }.map(\.id).sorted(),
                       MediaEncoding.videoTargets.map(\.key).sorted())
        XCTAssertEqual(FormatRegistry.known.filter { $0.category == .audio && $0.writable }.map(\.id).sorted(),
                       MediaEncoding.audioTargets.map(\.key).sorted())
    }

    func testAudioIsNeverTurnedIntoVideoAndFfmpegIsUnavailableUntilInstalled() {
        XCTAssertNil(ArchiveBuilders.route("mp3", "mp4", converter.edges))
        XCTAssertNil(ArchiveBuilders.route("wav", "gif", converter.edges))

        let status = converter.status()
        XCTAssertEqual(status.isAvailable, Self.tools != nil)
        if Self.tools == nil { XCTAssertEqual(status.reasonKey, "engine.reason.not_installed") }
    }

    func testEdgesKeepFileesOrderAndCosts() {
        let videos = FormatRegistry.known.filter { $0.category == .video }.count
        let audios = FormatRegistry.known.filter { $0.category == .audio }.count
        // Speech → TXT comes after Filee's edges, on macOS 26 or later.
        var speech = 0
        if #available(macOS 26.0, *) { speech = videos + audios }
        XCTAssertEqual(converter.edges.count, videos * (17 + 18 + 1) + videos + audios * 18 + 3 + speech)
        XCTAssertEqual(converter.edges.first, ConversionEdge("mp4", "mp4"))
        XCTAssertEqual(converter.edges[17], ConversionEdge("mp4", "mp3"))
        XCTAssertEqual(converter.edges.dropLast(speech).last, ConversionEdge("gif", "mov"))
        XCTAssertTrue(converter.edges.suffix(speech).allSatisfy { $0.to == "txt" })
    }

    // ───────────────────────── Command lines (no FFmpeg needed) ─────────────────────────

    func testCapabilitiesParseListingsAndRequireOnlyPlannedStreams() throws {
        let capabilities = FfmpegCapabilities.parse(encoders: """
         V..... = Video
         A..... = Audio
         V....D libtheora Theora
         A....D aac AAC
        """, muxers: """
         D.. = Demuxing supported
         .E. = Muxing supported
          E  ogg Ogg
         DE  mov,mp4 QuickTime / MOV
          D  matroska Matroska input only
        """)
        XCTAssertEqual(capabilities.encoders, ["libtheora", "aac"])
        XCTAssertEqual(capabilities.muxers, ["ogg", "mov", "mp4"])
        let info = MediaInfo(1, Self.hd, AudioStreamInfo(2, 44100), nil)
        func plan(_ target: String, _ options: MediaOptions = MediaOptions()) throws -> [FfmpegPass] {
            try MediaEncoding.plan("/in.mkv", "/out." + target, target, options, info, root)
        }
        XCTAssertThrowsError(try capabilities.validate(plan("ogv"), target: "ogv")) {
            XCTAssertTrue($0.localizedDescription.contains("libvorbis"))
            XCTAssertFalse($0.localizedDescription.contains("libtheora"))
        }
        try capabilities.validate(plan("ogv", options { $0.removeAudio = true }), target: "ogv")
        let noAudio = try MediaEncoding.plan("/in.mkv", "/out.ogv", "ogv", MediaOptions(), MediaInfo(1, Self.hd, nil, nil), root)
        try capabilities.validate(noAudio, target: "ogv")
        XCTAssertThrowsError(try capabilities.validate(plan("amr"), target: "amr")) {
            XCTAssertTrue($0.localizedDescription.contains("libopencore_amrnb"))
            XCTAssertTrue($0.localizedDescription.contains("output formats: amr"))
        }
        let gif = try plan("gif")
        try FfmpegCapabilities(encoders: ["png", "gif", "wrapped_avframe"], muxers: ["image2", "null", "gif"]).validate(gif, target: "gif")
        XCTAssertThrowsError(try FfmpegCapabilities(encoders: ["png", "gif"], muxers: ["image2", "null", "gif"]).validate(gif, target: "gif")) {
            XCTAssertTrue($0.localizedDescription.contains("wrapped_avframe"))
        }
        try FfmpegCapabilities(encoders: [], muxers: ["image2"]).validate(
            [FfmpegPass(arguments: ["-c:v", "copy", "-f", "image2", "/cover.png"], weight: 1)], target: "png")
    }

    func testMissingCapabilitiesPreserveOutputAndRefreshWhenExecutableChanges() async throws {
        let savedCopies = EngineEnvironment.ownCopies
        defer { EngineEnvironment.ownCopies = savedCopies }
        let folder = try newFolder(), input = FilePath.combine(folder, "tone.wav")
        let executable = FilePath.combine(folder, "ffmpeg"), output = FilePath.combine(folder, "result.amr")
        let script = #"""
        #!/bin/sh
        bin=$(dirname "$0")
        echo query >> "$bin/queries"
        case "$2" in
          -encoders) echo ' A..... aac AAC'; exit 0;;
          -muxers) echo ' E amr AMR'; exit 0;;
        esac
        echo converted > "$bin/converted"
        exit 8
        """#
        func writeExecutable(_ path: String, _ text: String) throws {
            try Data(text.utf8).write(to: URL(fileURLWithPath: path), options: .atomic)
            try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: path)
        }
        try writeExecutable(executable, script)
        try writeExecutable(FilePath.combine(folder, "ffprobe"), "#!/bin/sh\necho '{\"streams\":[{\"codec_type\":\"audio\",\"channels\":1,\"sample_rate\":\"8000\"}],\"format\":{\"duration\":\"1\"}}'\n")
        try Data("input".utf8).write(to: URL(fileURLWithPath: input))
        let original = Data("keep the existing file".utf8)
        try original.write(to: URL(fileURLWithPath: output))
        EngineEnvironment.ownCopies = ["ffmpeg": folder]
        let step = ConversionStep(inputPath: input, from: "wav", to: "amr", preset: Preset(),
                                  output: EbookTestOutput(FilePath.combine(folder, "result")), workDirectory: folder)
        for _ in 0..<2 {
            do { _ = try await FfmpegConverter().convert(step, progress: nil); XCTFail("Missing AMR encoder must fail") }
            catch { XCTAssertTrue(error.localizedDescription.contains("libopencore_amrnb"), error.localizedDescription) }
            XCTAssertEqual(try Data(contentsOf: URL(fileURLWithPath: output)), original)
        }
        XCTAssertFalse(FileManager.default.fileExists(atPath: FilePath.combine(folder, "converted")))
        func queries() throws -> Int { try String(contentsOfFile: FilePath.combine(folder, "queries"), encoding: .utf8).split(separator: "\n").count }
        XCTAssertEqual(try queries(), 2)

        try writeExecutable(executable, script.replacingOccurrences(of: "A..... aac AAC", with: "A..... libopencore_amrnb AMR"))
        let updated = try await FfmpegCapabilities.read(executable)
        XCTAssertTrue(updated.encoders.contains("libopencore_amrnb"))
        XCTAssertEqual(try queries(), 4)

        try writeExecutable(executable, "#!/bin/sh\necho query >> '" + FilePath.combine(folder, "queries") + "'\nexit 9\n")
        for _ in 0..<2 {
            do { _ = try await FfmpegCapabilities.read(executable); XCTFail("A failed capability query must fail") }
            catch { XCTAssertTrue(error.localizedDescription.contains("exit code 9")) }
        }
        XCTAssertEqual(try queries(), 6, "Failed queries must not be cached")
        let cancelled = Task {
            withUnsafeCurrentTask { $0?.cancel() }
            return try await FfmpegCapabilities.read(executable)
        }
        do { _ = try await cancelled.value; XCTFail("Cancellation must propagate") }
        catch { XCTAssertTrue(error is CancellationError) }
        XCTAssertEqual(try queries(), 6)
    }

    private func args(_ target: String, _ options: MediaOptions = MediaOptions(), info: MediaInfo? = nil) throws -> [String] {
        let passes = try MediaEncoding.plan("in.mkv", "out." + target, target, options,
                                            info ?? MediaInfo(10, Self.hd, AudioStreamInfo(6, 44100), nil), "work")
        XCTAssertEqual(passes.count, 1)
        return passes[0].arguments
    }

    private func after(_ args: [String], _ option: String) -> String? { args.firstIndex(of: option).map { args[$0 + 1] } }

    private func options(_ change: (inout MediaOptions) -> Void) -> MediaOptions {
        var options = MediaOptions()
        change(&options)
        return options
    }

    func testQualityBitrateAndSizeOptionsReachTheEncoders() throws {
        let mp4 = try args("mp4", options { $0.quality = .high; $0.maxHeight = 720 })
        XCTAssertEqual(after(mp4, "-c:v"), "libx264")
        XCTAssertEqual(after(mp4, "-crf"), "18")
        XCTAssertEqual(after(mp4, "-vf"), "scale=w=-2:h='trunc(min(ih,720)/2)*2'")
        XCTAssertEqual(after(mp4, "-movflags"), "+faststart")
        XCTAssertEqual(after(mp4, "-b:a"), "768k") // 256k per stereo pair × 3 pairs (5.1)
        XCTAssertEqual(after(mp4, "-f"), "mp4")

        let webm = try args("webm", options { $0.quality = .small; $0.removeAudio = true })
        XCTAssertEqual(Array(webm.drop { $0 != "-b:v" }.prefix(4)), ["-b:v", "0", "-crf", "38"])
        XCTAssertTrue(webm.contains("-an"))
        XCTAssertFalse(webm.contains("0:a:0"))

        let mp3 = try args("mp3", options { $0.audioBitrateKbps = 130 })
        XCTAssertEqual(after(mp3, "-b:a"), "128k") // snapped to the MP3 bitrate table
        XCTAssertFalse(mp3.contains("-q:a"))
        XCTAssertEqual(after(try args("mp3"), "-q:a"), "2") // VBR V2 by default

        XCTAssertEqual(after(try args("wma"), "-ac"), "2") // WMA holds two channels at most
        XCTAssertEqual(after(try args("amr"), "-ar"), "8000")
        XCTAssertEqual(after(try args("mpg"), "-r"), "30000/1001")
        XCTAssertEqual(after(try args("vob"), "-b:a"), "448k") // DVD 5.1
    }

    func testChannelsSampleRateAndBitDepthReachTheAudioEncoders() throws {
        // Low Opus bitrates for speech, mono (#37).
        let opus = try args("opus", options { $0.audioBitrateKbps = 32; $0.audioChannels = 1 })
        XCTAssertEqual(after(opus, "-b:a"), "32k")
        XCTAssertEqual(after(opus, "-ac"), "1")
        XCTAssertFalse(try args("opus").contains("-ac"))

        let wav = try args("wav", options { $0.audioChannels = 1; $0.audioSampleRate = 16000; $0.wavFormat = .pcm24 })
        XCTAssertEqual(after(wav, "-c:a"), "pcm_s24le")
        XCTAssertEqual(after(wav, "-ac"), "1")
        XCTAssertEqual(after(wav, "-ar"), "16000")
        XCTAssertEqual(after(try args("wav"), "-c:a"), "pcm_s16le") // 16-bit stays the default
        XCTAssertFalse(try args("wav").contains("-ar"))
        XCTAssertEqual(after(try args("wav", options { $0.wavFormat = .pcm8 }), "-c:a"), "pcm_u8")
        XCTAssertEqual(after(try args("wav", options { $0.wavFormat = .float32 }), "-c:a"), "pcm_f32le")

        // The sample rate is a WAV option only; AMR keeps its fixed mono 8 kHz.
        XCTAssertFalse(try args("flac", options { $0.audioSampleRate = 16000 }).contains("-ar"))
        let amr = try args("amr", options { $0.audioChannels = 2 })
        for (index, value) in amr.enumerated() where index > 0 && amr[index - 1] == "-ac" { XCTAssertEqual(value, "1") }
    }

    func testDvdAndDvFramesAreLetterboxedIntoTheNearestTvShape() {
        // 16:9 source: fills the anamorphic 16:9 NTSC frame.
        XCTAssertEqual(MediaEncoding.dvdOrDvFilter(Self.hd, pal: false), "scale=720:480,pad=720:480:(ow-iw)/2:(oh-ih)/2:black,setdar=16/9")
        // 4:3 source at PAL.
        XCTAssertEqual(MediaEncoding.dvdOrDvFilter(VideoStreamInfo(640, 480, 1, 0, 25), pal: true),
                       "scale=720:576,pad=720:576:(ow-iw)/2:(oh-ih)/2:black,setdar=4/3")
        // Cinemascope 2.39:1: 16:9 frame with bars above and below.
        XCTAssertEqual(MediaEncoding.dvdOrDvFilter(VideoStreamInfo(1920, 804, 1, 0, 24), pal: false),
                       "scale=720:358,pad=720:480:(ow-iw)/2:(oh-ih)/2:black,setdar=16/9")
        // Portrait phone video (landscape pixels + 90° rotation): 4:3 frame with bars left and right.
        XCTAssertEqual(MediaEncoding.dvdOrDvFilter(VideoStreamInfo(1920, 1080, 1, -90, 30), pal: false),
                       "scale=304:480,pad=720:480:(ow-iw)/2:(oh-ih)/2:black,setdar=4/3")

        XCTAssertTrue(MediaEncoding.isPal(25))
        XCTAssertTrue(MediaEncoding.isPal(50))
        XCTAssertFalse(MediaEncoding.isPal(29.97))
        XCTAssertFalse(MediaEncoding.isPal(0))
    }

    func testFrameRatesAreMadeEncodable() {
        let cases: [(Double, String?, String)] = [
            (29.97003, "30000/1001", "30000/1001"), (25, "25", "25"), (29.87, "30", "30000/1001"), (15, "15", "30"), (0, nil, "25"),
        ]
        for (fps, nearest, broadcast) in cases {
            XCTAssertEqual(MediaEncoding.nearestRate(fps), nearest, "\(fps)")
            XCTAssertEqual(MediaEncoding.broadcastRate(fps), broadcast, "\(fps)")
        }
    }

    func testGifUsesAPalettePassAndLimitsSize() throws {
        let passes = try MediaEncoding.plan("in.mp4", "out.gif", "gif", options { $0.maxHeight = 200 },
                                            MediaInfo(3, Self.hd, nil, nil), "work")
        XCTAssertEqual(passes.count, 2)
        XCTAssertEqual(passes.reduce(0) { $0 + $1.weight }, 1, accuracy: 1e-6)
        let first = passes[0].arguments
        let palette = try XCTUnwrap(after(first, "image2"))
        XCTAssertTrue(palette.hasPrefix(FilePath.combine("work", "palette-")), palette)
        XCTAssertTrue(try XCTUnwrap(after(first, "-filter_complex")).contains("palettegen"))
        let second = passes[1].arguments
        XCTAssertEqual(second[try XCTUnwrap(second.lastIndex(of: "-i")) + 1], palette)
        XCTAssertTrue(try XCTUnwrap(after(second, "-filter_complex")).contains("fps=12,scale=w='min(iw,480)':h='min(ih,200)'"))
        XCTAssertTrue(try XCTUnwrap(after(second, "-filter_complex")).contains("paletteuse"))
    }

    func testMissingStreamsAreReportedClearly() throws {
        let silent = MediaInfo(1, Self.hd, nil, nil)
        let noVideo = MediaInfo(1, nil, AudioStreamInfo(2, 48000), nil)
        XCTAssertThrowsError(try args("mp3", info: silent)) { XCTAssertEqual($0.localizedDescription, "The file has no audio track.") }
        XCTAssertThrowsError(try args("mp4", info: noVideo)) { XCTAssertEqual($0.localizedDescription, "The file has no video stream.") }
        // Video without sound converts to video without an audio track.
        XCTAssertTrue(try args("mkv", info: silent).contains("-an"))
    }

    func testProbeOutputIsParsed() throws {
        let json = """
            {
              "streams": [
                { "index": 0, "codec_name": "h264", "codec_type": "video", "width": 1920, "height": 1080,
                  "sample_aspect_ratio": "1:1", "r_frame_rate": "30/1", "avg_frame_rate": "30000/1001",
                  "disposition": { "attached_pic": 0 }, "side_data_list": [ { "side_data_type": "Display Matrix", "rotation": -90 } ] },
                { "index": 1, "codec_name": "aac", "codec_type": "audio", "channels": 2, "sample_rate": "48000", "duration": "12.5" },
                { "index": 2, "codec_name": "mjpeg", "codec_type": "video", "width": 300, "height": 300,
                  "disposition": { "attached_pic": 1 } }
              ],
              "format": { "duration": "12.480000" }
            }
            """
        let info = try MediaInfo.parse(json)
        XCTAssertEqual(try XCTUnwrap(info.duration), 12.48, accuracy: 0.001)
        XCTAssertEqual(info.video, VideoStreamInfo(1920, 1080, 1, -90, 30000 / 1001.0, nominalFrameRate: 30))
        XCTAssertEqual(try XCTUnwrap(info.video).displayAspect, 9 / 16.0, accuracy: 0.001)
        XCTAssertEqual(info.audio, AudioStreamInfo(2, 48000))
        XCTAssertEqual(info.coverStreamIndex, 2)

        let raw = try MediaInfo.parse(#"{ "streams": [ { "index": 0, "codec_type": "audio", "channels": 1, "sample_rate": "8000" } ], "format": {} }"#)
        XCTAssertNil(raw.duration)
        XCTAssertNil(raw.video)
    }

    func testStaticGifWebmUsesItsFrameDelayWithoutChangingAnimatedGifs() throws {
        let cases: [(String, String, String?)] = [
            ("1", "100/10", "10.0"), ("1", "100/40", "2.5"),
            ("3", "5/1", nil), ("N/A", "10/1", nil), ("1", "0/0", nil),
        ]
        for (frames, rate, expected) in cases {
            let info = try MediaInfo.parse("""
                {"streams":[{"codec_type":"video","width":96,"height":64,
                "avg_frame_rate":"\(rate)","r_frame_rate":"0/0","nb_frames":"\(frames)"}]}
                """)
            XCTAssertEqual(info.video?.frameCount, Int(frames) ?? 0)
            for (input, target) in [("input.GIF", "webm"), ("input.mp4", "webm"), ("input.gif", "mp4")] {
                let args = try MediaEncoding.plan(input, "out." + target, target, MediaOptions(), info, root)[0].arguments
                let actual = args.firstIndex(of: "-r").map { args[$0 + 1] }
                XCTAssertEqual(actual, input == "input.GIF" ? expected : nil)
            }
        }
    }

    func testFfmpegProgressAndErrorsAreRead() {
        XCTAssertEqual(FfmpegRunner.parsePosition("out_time_us=2500000"), 2.5)
        XCTAssertNil(FfmpegRunner.parsePosition("out_time_us=N/A"))
        XCTAssertEqual(FfmpegRunner.parsePosition("frame_time=1.25"), 1.25)
        XCTAssertNil(FfmpegRunner.parsePosition("progress=continue"))
        XCTAssertEqual(FfmpegRunner.summarize("[wmav2 @ 000001e0] too many channels: got 6, need 2 or fewer\r\n"
                                              + "[aost#0:1/wmav2 @ 000001e0] [enc:wmav2 @ 000001e0] Error while opening encoder\r\n"),
                       "too many channels: got 6, need 2 or fewer Error while opening encoder")
        XCTAssertEqual(MediaEncoding.formatSeconds(0.2), "0.2")
        XCTAssertEqual(MediaEncoding.formatSeconds(1.248), "1.248")
        XCTAssertEqual(MediaEncoding.formatSeconds(0.0005), "0.001")
        XCTAssertEqual(MediaEncoding.formatSeconds(0), "0")
        XCTAssertEqual(MediaEncoding.formatSeconds(0.105 / 10), "0.011") // 15 digits first, as .NET: 0.0105 → 0.011
        XCTAssertEqual(MediaEncoding.formatSeconds(9.2e16), "92000000000000000")
    }

    /// A tool that stops writing is killed after the stall timeout (FFmpeg's is 10 minutes; a silent stand-in here).
    func testASilentProcessIsStoppedByTheStallWatchdog() async throws {
        let marker = "37.\(Int.random(in: 100...999))"
        let started = Date()
        do {
            _ = try await FfmpegRunner.run("/bin/sleep", [marker], onPosition: nil, stallTimeout: 1.5)
            XCTFail("the silent process was not stopped")
        } catch let error as FfmpegRunner.StallError {
            XCTAssertTrue(error.localizedDescription.hasPrefix("FFmpeg stopped responding"), error.localizedDescription)
        }
        XCTAssertLessThan(Date().timeIntervalSince(started), 10)
        XCTAssertEqual(try ProcessRunner.runBlocking("/usr/bin/pgrep", ["-f", "sleep \(marker)"], timeout: 10).exitCode, 1)
    }

    // ───────────────────────── Real conversions ─────────────────────────

    /// Writes a test clip with FFmpeg: moving test pattern (+ a 440 Hz tone unless `audio` is false).
    private func makeClip(_ folder: String, _ name: String, seconds: Double = 2, size: String = "320x240", fps: Int = 25,
                          audio: Bool = true, channels: Int = 2, extra: [String] = []) async throws -> String {
        let path = FilePath.combine(folder, name)
        var args = ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi", "-i", "testsrc2=size=\(size):rate=\(fps):duration=\(seconds)"]
        if audio { args += ["-f", "lavfi", "-i", "sine=frequency=440:sample_rate=44100:duration=\(seconds)", "-ac", String(channels)] }
        try await run(try XCTUnwrap(Self.tools).ffmpeg, args + extra + [path])
        return path
    }

    /// A WAV tone (44.1 kHz stereo).
    private func makeTone(_ folder: String, _ name: String, seconds: Double = 2) async throws -> String {
        let path = FilePath.combine(folder, name)
        try await run(try XCTUnwrap(Self.tools).ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi",
                                                       "-i", "sine=frequency=440:sample_rate=44100:duration=\(seconds)", "-ac", "2", path])
        return path
    }

    private func run(_ exe: String, _ args: [String]) async throws {
        let result = try await ProcessRunner.run(exe, args, timeout: 120)
        XCTAssertEqual(result.exitCode, 0, result.standardError)
    }

    /// What ffprobe sees in a file.
    private struct Probed {
        let duration: Double
        let streams: [Track]
        var video: Track? { streams.first { $0.type == "video" && !$0.cover } }
        var audio: Track? { streams.first { $0.type == "audio" } }
    }

    private struct Track {
        let type: String, codec: String
        let width: Int, height: Int, channels: Int, sampleRate: Int
        let bitRate: Int64
        let cover: Bool
        let frames: Int
    }

    private func probe(_ path: String) async throws -> Probed {
        let result = try await ProcessRunner.run(try XCTUnwrap(Self.tools).ffprobe,
                                                 ["-v", "error", "-count_frames", "-print_format", "json", "-show_format", "-show_streams", path],
                                                 timeout: 60)
        XCTAssertEqual(result.exitCode, 0, "ffprobe \(path): \(result.standardError)")
        let root = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(result.standardOutput.utf8)) as? [String: Any])
        func s(_ e: [String: Any], _ name: String) -> String { (e[name] as? String) ?? (e[name] as? NSNumber)?.stringValue ?? "" }
        func n(_ e: [String: Any], _ name: String) -> Int64 { Int64(s(e, name)) ?? 0 }
        let streams = (root["streams"] as? [[String: Any]] ?? []).map { stream in
            Track(type: s(stream, "codec_type"), codec: s(stream, "codec_name"), width: Int(n(stream, "width")), height: Int(n(stream, "height")),
                  channels: Int(n(stream, "channels")), sampleRate: Int(n(stream, "sample_rate")), bitRate: n(stream, "bit_rate"),
                  cover: ((stream["disposition"] as? [String: Any])?["attached_pic"] as? NSNumber)?.intValue == 1,
                  frames: Int(n(stream, "nb_read_frames")))
        }
        return Probed(duration: Double(s(root["format"] as? [String: Any] ?? [:], "duration")) ?? 0, streams: streams)
    }

    /// Converts like a job: next to the source, named after it.
    private func convert(_ input: String, _ target: String, _ media: MediaOptions = MediaOptions()) async throws -> String {
        var preset = Preset()
        preset.targetFormat = target
        preset.media = media
        let outputs = try await ArchiveBuilders.convert(converter, input, preset, work: try newFolder())
        XCTAssertEqual(outputs.count, 1)
        let output = try XCTUnwrap(outputs.first)
        XCTAssertEqual(FilePath.extension(output), "." + FormatRegistry.get(target).primaryExtension)
        return output
    }

    /// ffprobe's codec name for each encoder Filee uses.
    private static func decoded(_ encoder: String) -> String {
        switch encoder {
        case "libx264": "h264"
        case "libvpx-vp9": "vp9"
        case "libtheora": "theora"
        case "libopus": "opus"
        case "libmp3lame": "mp3"
        case "libvorbis": "vorbis"
        case "libopencore_amrnb": "amr_nb"
        default: encoder
        }
    }

    /// Encoders of the installed FFmpeg.
    private static let encoders: Set<String> = {
        guard let ffmpeg = tools?.ffmpeg, let result = try? ProcessRunner.runBlocking(ffmpeg, ["-hide_banner", "-encoders"], timeout: 30) else { return [] }
        return Set(result.standardOutput.components(separatedBy: "\n").compactMap { line in
            let parts = line.split(separator: " ")
            return parts.count >= 2 && parts[0].count == 6 ? String(parts[1]) : nil
        })
    }()

    /// The encoders a target needs that this FFmpeg lacks.
    private static func missingEncoders(_ target: String) -> [String] {
        guard let spec = MediaEncoding.videoTarget(target) ?? MediaEncoding.audioTarget(target) else { return [] }
        return [spec.videoCodec, spec.audioCodec].compactMap { $0 }.filter { !encoders.contains($0) }
    }

