    func testEveryTargetFormatIsWrittenWithThePlannedCodecs() async throws {
        try skipUnlessInstalled()
        let folder = try newFolder()
        let source = try await makeClip(folder, "all.mp4", seconds: 1, size: "160x120")
        let targets = MediaEncoding.videoTargets + MediaEncoding.audioTargets
        let unavailable = targets.map(\.key).filter { !Self.missingEncoders($0).isEmpty }
        if !unavailable.isEmpty {
            print("Not written by this FFmpeg (missing encoder): " + unavailable.map { "\($0) (\(Self.missingEncoders($0).joined(separator: ", ")))" }.joined(separator: "; "))
        }

        var failures: [String] = []
        var pending = targets.filter { !unavailable.contains($0.key) }[...]
        try await withThrowingTaskGroup(of: [String].self) { group in
            func startNext() {
                guard let (target, spec) = pending.popFirst() else { return }
                group.addTask { try await self.check(source, target, spec) }
            }
            for _ in 0..<3 { startNext() }
            while let found = try await group.next() {
                failures += found
                startNext()
            }
        }
        XCTAssertEqual(failures, [])
    }

    private func check(_ source: String, _ target: String, _ spec: MediaTarget) async throws -> [String] {
        var failures: [String] = []
        do {
            let probed = try await probe(try await convert(source, target))
            if let codec = spec.videoCodec, probed.video?.codec != Self.decoded(codec) { failures.append("\(target): video \(probed.video?.codec ?? "none")") }
            if spec.videoCodec == nil, probed.video != nil { failures.append("\(target): unexpected video stream") }
            if probed.audio?.codec != Self.decoded(spec.audioCodec) { failures.append("\(target): audio \(probed.audio?.codec ?? "none")") }
            if !(0.7...1.5).contains(probed.duration) { failures.append("\(target): duration \(probed.duration)") }
            if target == "vob" || target == "dv", let frame = probed.video, (frame.width, frame.height) != (720, 576) { // 25 fps = PAL
                failures.append("\(target): frame \(frame.width)×\(frame.height)")
            }
        } catch {
            failures.append("\(target): \(error.localizedDescription)")
        }
        return failures
    }

