        XCTAssertEqual(opus.audio?.channels, 1)
        let wav = try await probe(try await convert(tone, "wav", options { $0.audioChannels = 1; $0.audioSampleRate = 8000; $0.wavFormat = .pcm8 }))
        XCTAssertEqual(wav.audio?.codec, "pcm_u8")
        XCTAssertEqual(wav.audio?.channels, 1)
        XCTAssertEqual(wav.audio?.sampleRate, 8000)
        let float32 = try await probe(try await convert(tone, "wav", options { $0.wavFormat = .float32 }))
        XCTAssertEqual(float32.audio?.codec, "pcm_f32le")
        XCTAssertEqual(float32.audio?.channels, 2)
        XCTAssertEqual(float32.audio?.sampleRate, 44100)
    }

    func testVideoWithoutSoundConvertsButHasNoAudioToExtract() async throws {
        try skipUnlessInstalled()
        let source = try await makeClip(try newFolder(), "silent.mp4", audio: false)
        let probed = try await probe(try await convert(source, "webm"))
        XCTAssertEqual(probed.video?.codec, "vp9")
        XCTAssertNil(probed.audio)

        do {
            _ = try await convert(source, "mp3")
            XCTFail("a silent video became an MP3")
        } catch {
            XCTAssertTrue(error.localizedDescription.contains("no audio track"), error.localizedDescription)
        }
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: FilePath.directoryName(source)!).filter { $0.hasSuffix(".mp3") }, [])
    }

    func testCoverArtAndTagsAreKept() async throws {
        try skipUnlessInstalled()
        let tools = try XCTUnwrap(Self.tools)
        let folder = try newFolder()
        let cover = FilePath.combine(folder, "cover.png")
        try await run(tools.ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi", "-i", "testsrc2=size=200x200", "-frames:v", "1", cover])
        let song = FilePath.combine(folder, "song.mp3")
        try await run(tools.ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi", "-i", "sine=duration=2", "-i", cover,
                                     "-map", "0:a", "-map", "1:v", "-c:v", "copy", "-disposition:v:0", "attached_pic", "-metadata", "title=노래 제목", song])

        // FLAC and M4A take a picture stream; Opus and Ogg a METADATA_BLOCK_PICTURE comment; MKA an attachment.
        var skipped: [String] = []
        for target in ["flac", "m4a", "opus", "ogg", "mka"] {
            if !Self.missingEncoders(target).isEmpty {
                skipped.append(target)
                continue
            }
            let output = try await convert(song, target)
            let probed = try await probe(output)
            XCTAssertTrue(probed.streams.contains { $0.cover && $0.codec == "png" }, "\(target): no cover")
            let tags = try await ProcessRunner.run(tools.ffprobe, ["-v", "error", "-show_entries", "format_tags=title,major_brand:stream_tags=title",
                                                                    "-of", "json", output], timeout: 60)
            XCTAssertTrue(tags.standardOutput.contains("노래 제목"), "\(target): title lost")
        }
        if !skipped.isEmpty { print("Not written by this FFmpeg (missing encoder): \(skipped)") }
    }

    // ───────────────────────── Progress and cancellation ─────────────────────────

    private final class FolderAllocator: OutputAllocator, @unchecked Sendable {
        private let folder: String
        private(set) var allocated: [String] = []
        init(_ folder: String) { self.folder = folder }

        func allocate(_ extension: String, suffix: String?) throws -> String? {
            let path = FilePath.combine(folder, "out\(suffix ?? "").\(`extension`)")
            allocated.append(path)
            return path
        }
    }

    /// Records every reported value synchronously.
    private final class Recorder: @unchecked Sendable {
        private let lock = NSLock()
        private var stored: [Double] = []
        private let onReport: (@Sendable (Double) -> Void)?
        init(_ onReport: (@Sendable (Double) -> Void)? = nil) { self.onReport = onReport }
        var values: [Double] { lock.withLock { stored } }
        var handler: ProgressHandler {
            { [self] value in
                lock.withLock { stored.append(value) }
                onReport?(value)
            }
        }
    }

    private func step(_ input: String, _ from: String, _ to: String, _ folder: String, _ media: MediaOptions = MediaOptions()) -> ConversionStep {
        var preset = Preset()
        preset.targetFormat = to
        preset.media = media
        return ConversionStep(inputPath: input, from: from, to: to, preset: preset, output: FolderAllocator(folder), workDirectory: folder)
    }

    func testProgressRisesWhileFfmpegWorks() async throws {
        try skipUnlessInstalled()
        let folder = try newFolder()
        // Long enough for several of FFmpeg's half-second progress reports.
        let source = try await makeClip(folder, "long.mp4", seconds: 40, size: "640x360", extra: ["-c:v", "libx264", "-preset", "ultrafast"])
        XCTAssertTrue(converter.status().isAvailable)

        let recorder = Recorder()
        let outputs = try await converter.convert(step(source, "mp4", "mkv", folder, options { $0.quality = .high }), progress: recorder.handler)

        XCTAssertTrue(FileManager.default.fileExists(try XCTUnwrap(outputs.first)))
        let values = recorder.values
        XCTAssertEqual(values.last, 1)
        XCTAssertTrue(zip(values, values.dropFirst()).allSatisfy { $0 <= $1 }, "\(values)")
        XCTAssertGreaterThanOrEqual(values.filter { $0 > 0.02 && $0 < 1 }.count, 3, "\(values)")
    }

    func testGifPalettePassReportsProgressToo() async throws {
        try skipUnlessInstalled()
        let folder = try newFolder()
        let source = try await makeClip(folder, "gifprogress.mp4", seconds: 30, size: "640x360", audio: false,
                                        extra: ["-c:v", "libx264", "-preset", "ultrafast"])
        let recorder = Recorder()
        _ = converter.status()
        _ = try await converter.convert(step(source, "mp4", "gif", folder, options { $0.quality = .small }), progress: recorder.handler)
        // The palette pass covers the first 40 %: values inside it prove its progress is read.
        XCTAssertTrue(recorder.values.contains { $0 > 0.05 && $0 < 0.4 }, "\(recorder.values)")
    }

    func testCancellingKillsFfmpegAndRemovesThePartialOutput() async throws {
        try skipUnlessInstalled()
        let folder = try newFolder()
        let source = try await makeClip(folder, "cancel.mp4", seconds: 60, size: "1280x720", extra: ["-c:v", "libx264", "-preset", "ultrafast"])
        let canceller = Canceller()
        let recorder = Recorder { if $0 > 0.05 { canceller.cancel() } }
        _ = converter.status()
        let step = self.step(source, "mp4", "webm", folder, options { $0.quality = .high })
        let started = Date()
        let task = Task { [converter] in try await converter.convert(step, progress: recorder.handler) }
        canceller.set(task)
        let fallback = Task { // in case no progress arrives at all
            try await Task.sleep(nanoseconds: 30_000_000_000)
            canceller.cancel()
        }
        defer { fallback.cancel() }

        do {
            _ = try await task.value
            XCTFail("the conversion was not cancelled")
        } catch {
            XCTAssertTrue(error is CancellationError, "\(error)")
        }

        XCTAssertLessThan(Date().timeIntervalSince(started), 60, "VP9 encoding of the whole clip should not have finished")
        let output = try XCTUnwrap((step.output as? FolderAllocator)?.allocated.first)
        XCTAssertFalse(FileManager.default.fileExists(output))
        // No FFmpeg of ours is left running (it would keep the CPU busy and the output locked).
        var running = true
        for _ in 0..<50 {
            running = (try ProcessRunner.runBlocking("/usr/bin/pgrep", ["-f", source], timeout: 10)).exitCode == 0
            if !running { break }
            try await Task.sleep(nanoseconds: 200_000_000)
        }
        XCTAssertFalse(running, "an FFmpeg process survived the cancel")
    }

    private final class Canceller: @unchecked Sendable {
        private let lock = NSLock()
        private var task: Task<[String], Error>?
        private var requested = false

        func set(_ task: Task<[String], Error>) {
            lock.withLock {
                self.task = task
                if requested { task.cancel() }
            }
        }

        func cancel() {
            lock.withLock {
                requested = true
                task?.cancel()
            }
        }
    }

    // ───────────────────────── Finding FFmpeg (PortableEngineTests, OwnCopyTests) ─────────────────────────

    func testFfmpegRequiresBothToolsInTheSameFolder() throws {
        let dir = try newFolder()
        try Data("binary".utf8).write(to: URL(fileURLWithPath: FilePath.combine(dir, "ffmpeg")))
        XCTAssertNil(EngineEnvironment.folderWithPrograms("ffmpeg", dir))
        try Data("binary".utf8).write(to: URL(fileURLWithPath: FilePath.combine(dir, "ffprobe")))
        XCTAssertEqual(EngineEnvironment.folderWithPrograms("ffmpeg", dir), dir)
    }

    func testTheUsersOwnCopyWinsAndAFolderWithoutEveryProgramIsNotUsed() throws {
        let dir = try newFolder()
        defer { EngineEnvironment.ownCopies = [:] }
        func program(_ relative: String) throws -> String {
            let path = FilePath.combine(dir, relative)
            try FileManager.default.createDirectoryIfNeeded(FilePath.directoryName(path)!)
            try Data([0x4D, 0x5A]).write(to: URL(fileURLWithPath: path))
            return path
        }
        let ffmpeg = try program("ffmpeg/bin/ffmpeg"), ffprobe = try program("ffmpeg/bin/ffprobe")
        EngineEnvironment.ownCopies = ["ffmpeg": FilePath.combine(dir, "ffmpeg")] // the folder of an FFmpeg build: its bin/ is found
        XCTAssertEqual(FfmpegConverter.locate()?.ffmpeg, ffmpeg)
        XCTAssertEqual(FfmpegConverter.locate()?.ffprobe, ffprobe)

        let lonely = try program("tools/ffmpeg")
        XCTAssertNil(EngineEnvironment.folderWithPrograms("ffmpeg", lonely))
        EngineEnvironment.ownCopies = ["ffmpeg": lonely]
        XCTAssertNil(EngineEnvironment.ownCopyFolder("ffmpeg"))
        XCTAssertNotEqual(FfmpegConverter.locate()?.ffmpeg, lonely)
    }
